import { MeshBasicNodeMaterial } from 'three/webgpu';
import { gsap } from 'gsap';
import { vec2, uv } from 'three/tsl';

/**
 * @typedef {Object} NodeConfig
 * @property {string} [imageUrl]
 * @property {Array<{name:string,params:any,trigger:string}>} [cinematicPrimitives]
 * @property {Array<{text:string,role:string,typography?:{fontSize?:number}}>} [textContent]
 * @property {any} [intent]
 */

/**
 * @typedef {Object} NodeContext
 * @property {any} THREE
 * @property {{loadTexture(url:string):Promise<any>}} textureLoader
 * @property {{loadGLB(url:string):Promise<any>}} glbLoader
 * @property {{loadVideo?: (url:string)=>Promise<any>}} videoLoader
 * @property {{fontAtlas:any}} fontAtlas
 * @property {{primitives:any}} primitives
 * @property {(event:string, payload:any)=>void} emit
 * @property {string} [tier]
 */

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry } = ctx.THREE;

  // Root container
  const root = new Group();

  // ----------- Geometry & Material -----------
  const width = 1.6; // aspect from 512x320
  const height = 1.0;
  const geometry = new PlaneGeometry(width, height);
  const material = new MeshBasicNodeMaterial({ color: 0xffffff, transparent: true });

  const mesh = new Mesh(geometry, material);
  root.add(mesh);

  // Load texture asynchronously
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      material.map = tex;
      material.needsUpdate = true;
    });
  }

  // ----------- Text (if any) -----------
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  for (const item of items) {
    const txt = ctx.fontAtlas.createText(item.text, {
      fontSize: item.typography?.fontSize ?? 0.13,
      color: config?.visualSpec?.colors?.paper ?? '#e8ecf2',
      align: 'left',
    });
    mesh.add(txt);
  }

  // ----------- Cinematic Primitives -----------
  const primitiveHandles = [];
  if (Array.isArray(config.cinematicPrimitives)) {
    for (const prim of config.cinematicPrimitives) {
      const fn = ctx.primitives[prim.name];
      if (typeof fn === 'function') {
        const handle = fn(root, prim.params || {});
        primitiveHandles.push(handle);
      }
    }
  }

  // ----------- Interaction Handlers -----------
  const timelines = [];

  const hoverEnter = () => {
    const tl = gsap.timeline();
    tl.to(root.position, { y: root.position.y + 0.15, duration: 0.3, ease: 'power2.out' });
    timelines.push(tl);
  };
  const hoverLeave = () => {
    const tl = gsap.timeline();
    tl.to(root.position, { y: root.position.y - 0.15, duration: 0.2, ease: 'power2.in' });
    timelines.push(tl);
  };
  const onClick = () => {
    ctx.emit('hub-pricing.select', {});
  };

  root.userData.handlers = {
    hoverEnter,
    hoverLeave,
    click: onClick,
  };

  // ----------- Cleanup -----------
  root.userData.cleanup = () => {
    // Dispose geometry & material
    geometry.dispose();
    material.dispose();

    // Kill GSAP timelines
    timelines.forEach((t) => t.kill());
    timelines.length = 0;

    // Cleanup primitives
    primitiveHandles.forEach((h) => {
      if (h && typeof h.cleanup === 'function') h.cleanup();
    });
    primitiveHandles.length = 0;
  };

  return root;
}
